// Global type declarations for NewMobility

/**
 * __non_webpack_require__ is a special token that webpack replaces with the
 * native Node.js `require` function, bypassing webpack's module resolution.
 * This is used in server-side code that needs to load Node-only modules
 * (like `fs` and `path`) without bundling them for the client.
 */
declare const __non_webpack_require__: NodeRequire
